// comment row-level security and integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); E5 AC2 cases added (mentions, turn into action).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  action,
  client,
  comment,
  createDatabase,
  inActorTransaction,
  migrateUp,
  site,
  sql,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const commentA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const mentioned = randomUUID();
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'S' as const,
});
const commentOf = (
  clientId: string,
  siteId: string | null,
  body: string,
  more: Partial<typeof comment.$inferInsert> = {},
) => ({ id: randomUUID(), clientId, siteId, body, authorId: staff.id, ...more });
const actionFrom = (commentId: string, sourceKind: 'comment' | 'manual') => ({
  id: randomUUID(),
  clientId: clientA,
  siteId: siteA,
  title: 'Check the ceiling height',
  ownerId: mentioned,
  due: '2026-11-13',
  sourceKind,
  sourceRef: commentId,
  commentId,
  createdBy: staff.id,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(comment)).map((r) => r.body).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx.insert(comment).values([
      commentOf(clientA, siteA, 'Installation moved to Tuesday', { visibility: 'client' }),
      commentOf(clientA, siteA, 'Can you check the ceiling height?', {
        id: commentA,
        mentions: [mentioned],
      }),
      commentOf(clientB, siteB, 'Waiting for the PO'),
    ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every comment', async () => {
  expect(await visibleTo(staff)).toHaveLength(3);
});

it('a client sees only its own comments marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['Installation moved to Tuesday']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(comment).values(commentOf(clientA, siteA, 'Hi')),
    ),
  ).rejects.toThrow();
});

it('a comment has a body and belongs to a project of its own client', async () => {
  await expect(asStaff((tx) => tx.insert(comment).values(commentOf(clientA, siteA, ' ')))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(comment).values(commentOf(clientA, null, 'Unlinked'))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(comment).values(commentOf(clientA, siteB, 'Wrong'))),
  ).rejects.toThrow();
});

it("a user's mentions are found by index (E5 AC2)", async () => {
  const mine = await asStaff((tx) =>
    tx
      .select()
      .from(comment)
      .where(sql`${comment.mentions} @> ARRAY[${mentioned}]::uuid[]`),
  );
  expect(mine.map((c) => c.id)).toEqual([commentA]);
});

it('an action turned from a comment links to it and says so in its source (E5 AC2)', async () => {
  await asStaff((tx) => tx.insert(action).values(actionFrom(commentA, 'comment')));
  await expect(asStaff((tx) => tx.insert(action).values(actionFrom(commentA, 'manual')))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(action).values(actionFrom(randomUUID(), 'comment'))),
  ).rejects.toThrow();
});
